pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameter: a dummy uint to satisfy the requirement of at least one fuzzed input
    // The property does not depend on any external adversary, but we must accept fuzz inputs
    // and ensure the reference always returns the same version string.
    function testFuzz_property(uint256 /*unused_fuzzed_param*/) public {
        // No domain restriction necessary; keep it wide so fuzzer can explore

        // call version() and capture its returned string via try/catch to be robust
        bool ok;
        string memory v;
        try c.version() returns (string memory s) {
            ok = true;
            v = s;
        } catch {
            // If version() reverts in either contract, this would indicate a difference,
            // but both reference and mutant are non-reverting for version(); mark as not ok
            ok = false;
            v = "";
        }

        // The universal property: reference always returns exactly "1.0.0" (non-reverting and value)
        // We assert that version() completed successfully and returned "1.0.0".
        assertTrue(ok && (keccak256(bytes(v)) == keccak256(bytes("1.0.0"))));
    }
}

