pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed param included to satisfy fuzzing requirement; version() takes no args,
    // so we still include a fuzzed bytes parameter which does not affect behavior
    // but lets the fuzzer explore inputs (the property is universal over calls).
    function testFuzz_property(bytes memory junk) public {
        // Keep the fuzzed domain wide; no assumptions needed.

        // Call version() and capture its return; the reference always returns exactly "1.0.0".
        string memory v = c.version();

        // Single assertion: the returned version string equals "1.0.0".
        // This holds for the reference contract for all inputs; the mutant that returns
        // "1.0.0-beta" will cause this assertion to fail for some fuzz input (indeed for any).
        assertTrue(keccak256(bytes(v)) == keccak256(bytes("1.0.0")));
    }
