contract InvMutTest {
    C public c;

    constructor(C _c) { c = _c; }

    // Call sequence: attempt to set L1 block values from msg.sender (the test caller).
    // We require the caller not to be the zero address to make parameters general.
    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        // Read depositor account as observed via public getter
        address depositor = c.depositorAccount();

        // If this test contract's caller (msg.sender) is the depositor, then calling
        // setL1BlockValues should succeed on the original and revert on the mutant.
        // To make a single general assertion that distinguishes P and M, we assert
        // that when msg.sender equals depositor, the call does NOT revert.
        // The verifier will check this holds on P and is violated by M.

        // Precondition for meaningful test: allow any inputs but ensure caller identity matters.
        require(msg.sender != address(0), "caller zero");

        // Perform the state-changing call; on the original contract this should succeed
        // when msg.sender == depositor, while the mutant inverts the require and will revert.
        c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        );

        // Assert the distinguishing property: if the caller equals the depositorAccount
        // then the call should have been allowed (i.e., caller == depositor implies true).
        // This is a simple boolean relation that holds on P but is violated by M.
        assert(!(msg.sender == depositor) == false);
    }

    // Allow receiving ETH if needed by caller, though not used here.
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        // require that the caller is not the depositor account to observe the difference
        require(caller != c.depositorAccount());
        bool reverted;
        // simulate call from `caller` by using low-level call: must encode call data
        bytes memory data = abi.encodeWithSelector(c.setL1BlockValues.selector,
            uint64(1), uint64(1), uint256(1), bytes32(0), uint64(1), bytes32(0), uint256(1), uint256(1)
        );
        // perform call as this contract but specifying target sender via tx.origin can't be changed; instead we observe behavior for non-depositor via direct call
        try c.setL1BlockValues(uint64(1), uint64(1), uint256(1), bytes32(0), uint64(1), bytes32(0), uint256(1), uint256(1)) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // Rule: if caller (msg.sender) is not depositorAccount, the call must revert on the original contract
        // We express this using the provided `caller` parameter: since we required caller != depositorAccount(),
        // the call initiated by this test (which is not the depositor) must revert.
        assert(reverted == true);
    }
    receive() external payable {}
}

