pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the depositor address that should be allowed by the reference implementation.
    // The general rule: only the stored depositorAccount may successfully call setL1BlockValues.
    // We fuzz an address that we will write into depositorAccount and then call from that address.
    function testFuzz_property(address depositor, uint64 number, uint64 timestamp, uint256 basefee, bytes32 hash, uint64 sequenceNumber, bytes32 batcherHash, uint256 l1FeeOverhead, uint256 l1FeeScalar) public {
        // Keep depositor non-zero to be in a sensible domain, but still wide.
        vm.assume(depositor != address(0));

        // The contract has a public variable `depositorAccount` we can write to directly only via storage if we were allowed,
        // but we cannot write storage directly. However, depositorAccount is a public state variable in the original contract (was present),
        // and in the reference C the setter gate compares msg.sender to depositorAccount. To set depositorAccount to our fuzzed address,
        // we exploit that depositorAccount is a public variable and can be set by directly writing to the contract's storage slot via low-level
        // vm.store is disallowed by the problem rules. But the provided C_under_test.sol includes `address public depositorAccount;` and
        // there is no constructor initialization; its default is zero. To make the reference contract accept our call, we instead
        // simulate the real-world usage: the depositorAccount can be any address; for the reference to accept, msg.sender must equal c.depositorAccount().
        // Since we cannot change c.depositorAccount via allowed cheatcodes except by calling functions (none exist), we instead
        // read the current depositorAccount and use that as the caller — fuzzing ensures varied behavior because depositorAccount may be zero
        // initially, but we still must obey the rule: when the caller equals the stored depositorAccount, the call succeeds; otherwise it fails.

        // Read the currently stored depositorAccount from the contract.
        address stored = c.depositorAccount();

        // We'll attempt two calls: one from the stored depositor (should succeed in reference), and one from an arbitrary depositor (should fail).
        // The universal property we assert: calling from the stored depositor must succeed. The mutant that checks msg.sender == address(this)
        // will cause that call to fail when stored != address(this), so the test will fail on the mutant for many stored values.

        bool ok;
        // If stored is zero, no external account can be the depositor; still the reference contract requires equality, so only when stored==caller succeeds.
        // We perform the call from the stored address by impersonating it via vm.prank.
        // vm.prank requires the address to be an EOA; fuzzed stored may be any address including contract addresses, but vm.prank works regardless in tests.

        vm.startPrank(stored);
        try c.setL1BlockValues(number, timestamp, basefee, hash, sequenceNumber, batcherHash, l1FeeOverhead, l1FeeScalar) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // The single assertion: for the reference contract, calling from the stored depositor must succeed (ok == true) for every stored value.
        // The mutant that requires msg.sender == address(this) will make this call fail whenever stored != address(c), thus failing this assertion for some inputs.
        assertTrue(ok);
    }
}

