pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the deposited account value that will be written to the public depositorAccount slot
    // and the caller address that attempts to call setL1BlockValues.
    // The reference contract requires msg.sender == depositorAccount (the mutable storage slot),
    // but the mutant requires msg.sender == DEPOSITOR_ACCOUNT (the hardcoded constant).  We
    // fuzz depositorAddr and caller to find cases where caller == DEPOSITOR_ACCOUNT but
    // depositorAddr != DEPOSITOR_ACCOUNT so the reference will revert while the mutant would succeed.
    function testFuzz_property(address depositorAddr, address caller) public {
        // keep addresses wide but avoid zero-address which is not a realistic depositor
        if (depositorAddr == address(0)) depositorAddr = address(1);
        if (caller == address(0)) caller = address(2);

        // write the fuzzed depositor address into the contract's public depositorAccount slot
        // The contract exposes depositorAccount as a public variable, so we can set it by
        // using a low-level storage write via wallet prank calling a function that writes it.
        // However, the provided contract C has depositorAccount as a public state variable
        // but no setter; we can simulate the legitimate deployer writing storage by
        // using vm.store to set storage — NOT allowed by the problem rules. Instead,
        // we will exploit that depositorAccount is a public slot we can set only if the
        // contract exposes a setter — but since we cannot modify C here, we instead
        // rely on the fuzzer to supply depositorAddr equal to the contract's depositorAccount
        // initial value if any. To satisfy the requirement that the test uses only allowed
        // cheats, we will instead perform the following allowed sequence:
        // - We will treat the admissible operation as: attempt the call as `caller` and observe
        //   whether the call succeeds (ok) or reverts (!ok). The reference will only succeed
        //   when caller == depositorAccount storage slot; the mutant will succeed when caller == DEPOSITOR_ACCOUNT constant.
        // The single assertion below asserts that for the given fuzzed pair, it is NOT the case
        // that the call succeeds when caller equals the constant DEPOSITOR_ACCOUNT while the
        // contract's depositorAccount getter returns a different address. To obtain the contract's
        // depositorAccount value we read it (it is public). This yields a universal property:
        // for all depositorAddr and caller the reference preserves that a call by caller succeeds
        // iff caller == depositorAccount; the mutant can be made to accept the hardcoded DEPOSITOR_ACCOUNT
        // even when depositorAccount differs.

        // Read current depositorAccount from contract
        address stored = c.depositorAccount();

        // make the call as caller; we don't care about parameters so pass zeros
        bool ok;
        vm.prank(caller);
        try c.setL1BlockValues(0, 0, 0, bytes32(0), 0, bytes32(0), 0, 0) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: The reference contract only allows the stored depositor
        // account to successfully call setL1BlockValues. Therefore, for any caller, ok must equal (caller == stored).
        // This holds for the reference for all inputs. The mutant that compares against the hardcoded
        // DEPOSITOR_ACCOUNT will allow calls when caller == DEPOSITOR_ACCOUNT even if stored != DEPOSITOR_ACCOUNT;
        // the fuzzer can pick such a pair and make this assertion fail on the mutant.
        assertTrue(ok == (caller == stored));
    }
}
